using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static class ValidateFiveHangars {
 static Transform root,exp;static Terrain terrain;static List<string> report=new List<string>();
 static void Check(bool pass,string message){report.Add((pass?"PASS ":"FAIL ")+message);}
 static float H(Vector3 p)=>terrain.SampleHeight(p)+terrain.transform.position.y;
 public static string Main(){root=GameObject.Find("New_Map").transform;exp=root.Find("11_Five_Hangar_Farm");terrain=root.GetComponentInChildren<Terrain>();report.Clear();Physics.SyncTransforms();
 var rs=root.GetComponentsInChildren<Renderer>();Check(root.GetComponentsInChildren<Transform>(true).Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject))==0,"No missing scripts");Check(rs.All(r=>r.sharedMaterials.All(m=>m&&m.shader&&m.shader.isSupported)),"Active renderer materials/shaders valid");Check(root.GetComponentsInChildren<MeshFilter>().All(m=>m.sharedMesh),"Active mesh references valid");Check(terrain.GetComponent<TerrainCollider>().terrainData==terrain.terrainData,"Terrain collider matches expanded terrain");
 var hs=exp.Cast<Transform>().Where(t=>t.name.StartsWith("Hangar ")).ToArray();Check(hs.Length==4&&root.Find("01_Modular_Hangar"),"Five hangars: original plus four larger halls");
 for(int i=2;i<=5;i++){var h=hs.Single(t=>t.name.StartsWith("Hangar "+i+" -"));Vector3 from=h.TransformPoint(new Vector3(1,3,20)),to=h.TransformPoint(new Vector3(1,3,12));var hits=Physics.RaycastAll(from,(to-from).normalized,Vector3.Distance(from,to));Check(hits.Any(x=>x.collider.transform.IsChildOf(h)&&x.collider.name.Contains("collision")),"Hangar "+i+" closed door blocks entry");}
 var piles=Object.FindObjectsByType<GrainPile>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(p=>p.gameObject.scene==root.gameObject.scene).ToArray();Check(piles.Length==5,"Five authored grain piles");foreach(var p in piles){if(!p.gameObject.activeInHierarchy){Check(!p.isActiveAndEnabled,p.name+" simulation disabled until hangar opens");continue;}p.Initialize();Check(p.Kilograms>1,p.name+" mass "+p.Kilograms.ToString("F0")+" kg");}
 var medium=piles.Where(p=>p.name.StartsWith("Hangar 2")||p.name.StartsWith("Hangar 3")).ToArray();var large=piles.Where(p=>p.name.StartsWith("Hangar 4")||p.name.StartsWith("Hangar 5")).ToArray();if(medium.Concat(large).All(p=>p.gameObject.activeInHierarchy))Check(large.Min(p=>p.Kilograms)>medium.Max(p=>p.Kilograms),"Large hangars contain more grain than medium hangars");else Check(medium.Concat(large).All(p=>!p.gameObject.activeInHierarchy),"Closed hangar grain stays inactive; no simulation initialized by audit");
 int blocked=0,total=0;for(int i=0;i<=24;i++){float t=i/24f;foreach(var pair in new[]{new[]{new Vector3(-175,0,Mathf.Lerp(-54,298,t)),Vector3.left},new[]{new Vector3(175,0,Mathf.Lerp(-54,298,t)),Vector3.right},new[]{new Vector3(Mathf.Lerp(-175,175,t),0,-53),Vector3.back},new[]{new Vector3(Mathf.Lerp(-175,175,t),0,297),Vector3.forward}}){var p=pair[0];p.y=H(p)+1.1f;var hits=Physics.RaycastAll(p,pair[1],10);total++;if(hits.Any(h=>h.collider.name=="Map edge barrier"))blocked++;}}Check(blocked==total,"Continuous perimeter collision sampled "+blocked+"/"+total);
 var road=File.ReadAllLines("output/NewMap/Revision2/road-centerline.csv").Skip(1).Select(l=>{var s=l.Split(',');return new Vector3(float.Parse(s[0],System.Globalization.CultureInfo.InvariantCulture),0,float.Parse(s[2],System.Globalization.CultureInfo.InvariantCulture));}).ToArray();var obstructions=new HashSet<string>();foreach(var p0 in road){var p=p0;p.y=H(p)+1.15f;foreach(var c in Physics.OverlapBox(p,new Vector3(1.65f,.65f,.6f),Quaternion.identity,~0,QueryTriggerInteraction.Ignore)){if(c is TerrainCollider||c.GetComponentInParent<PlayerController>()||!c.transform.IsChildOf(root))continue;obstructions.Add(c.name+" parent="+c.transform.parent.name+" at road="+p0+" bounds="+c.bounds);}}
 Check(obstructions.Count==0,"Main road walking corridor clear; obstructions="+obstructions.Count);foreach(var o in obstructions)report.Add("ROAD: "+o);
 int lodProblems=0;foreach(var lod in new[]{exp,root.Find("04_Mini_Village"),root.Find("12_Farmyards_and_boundaries")}.SelectMany(t=>t.GetComponentsInChildren<LODGroup>()))foreach(var level in lod.GetLODs())if(level.renderers.Any(r=>!r))lodProblems++;Check(lodProblems==0,"LOD renderer references intact");
 report.Add("Active renderers="+rs.Length+"; active transforms="+root.GetComponentsInChildren<Transform>().Length+"; five-hangar section mesh assets shared between buildings. No runtime economy/progression added.");
 string result=string.Join("\n",report);Directory.CreateDirectory("output/NewMap/FiveHangars");File.WriteAllText("output/NewMap/FiveHangars/validation.txt",result);return result;}
 public static string ClearFarmPlots(){root=GameObject.Find("New_Map").transform;terrain=root.GetComponentInChildren<Terrain>();var points=new[]{new Vector3(55,0,112),new Vector3(-58,0,153),new Vector3(-94,0,233),new Vector3(62,0,206)};int count=0;var landscape=root.Find("05_Landscape");foreach(var t in landscape.GetComponentsInChildren<Transform>().ToArray()){if(!t.gameObject.activeInHierarchy||t==landscape)continue;var lod=t.GetComponent<LODGroup>();if(!lod&&t.parent.GetComponentInParent<LODGroup>())continue;var rs=t.GetComponentsInChildren<Renderer>();if(rs.Length==0)continue;var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);bool hit=points.Any(p=>Mathf.Abs(b.center.x-p.x)<17+Mathf.Min(b.extents.x,8)&&Mathf.Abs(b.center.z-p.z-6)<20+Mathf.Min(b.extents.z,8));if(hit&&(lod||t.GetComponent<MeshRenderer>())){t.gameObject.SetActive(false);count++;}}EditorSceneManager.SaveScene(root.gameObject.scene);return "Cleared vegetation for new farm plots: "+count;}
}




